update public.poetry as p
set body = x.body
from (
  select x->>'slug' as slug, x->>'body' as body
  from jsonb_array_elements($bodies$[{"slug":"tum-p036","body":"اب بھی جب کبھی اچانک کہیں پہ\nلکھا ہوا تیرا نام جو نظر آئے\nدل ہر گز نہ سنبھل پائے\nکوئے ملامت کو جائے\nاک خیال سا ابھرتا ہوا\nذہن کے کسی انجان\nکونے سے نکلتا ہوا\nمیرے قلم کی نوک پہ آئے\nپر کچھ  نہ لکھا جائے\nکچھ نہ کہا جائے\nکچھ نہ سوچا جائے\nفقط اک خیال اور بس\nاور بس تیری یاد آئے۔۔۔"},{"slug":"tum-p037","body":"اک شور سا اٹھا ہے دل کے ویرانے سے\nوہ یاد لوٹ آئی ہے پھر کسی بہانے سے\n\nہم کو خود بھی نہ آئی خوشی راس\nکیا ہی شکوہ کرتے ہم زمانے سے\n\nتم تھے تب بھی خلش جگر میں رہی\nاب سوچتا ہوں کیا ہوتا تمہارے آنے سے\n\nمسرتیں اٹھنے لگی ہیں اپنے آشیانے سے\nدل بھرنے لگا ہے محبت کے خزانے سے\n\nاس سے پہلے کہ کہیں کے نہ رہیں احمد\nکچھ پل کو لوٹ آؤ کسی بہانے سے"},{"slug":"tum-p038","body":"تم نہیں ، وہ جس کی تلاش تھی مجھے\nوہ منزل جو کبھی آکاش تھی مجھے\nوہ راستے جو منزلوں سے تھے حسیں\nوہ زندگی ، جو حرف کاش تھی مجھے\nوہ درد میں سلگتا ہوا بےداغ دل\nبے چارگی میں الجھا ہوا بےتاب پل\nوہ سرد لہجوں میں چھپی تنہاروی\nاور آرزوؤں میں بھیگا ہوا بادل\nوہ خلاوں میں ڈوبا ہوا ستارہ\nجسے کھوج تھی اور ہی آکاش کی\nجسے ہم نے چاہا آج تک\nجس کی ہم نے تلاش کی\nوہ کہیں تم ہی تم میں کھو گیا\nجو ہے اب یہاں، وہ تم نہیں"},{"slug":"tum-p039","body":"چاند کی پگلی چاندنی میں آج کچھ تو خاص ہے\nہم تو ٹھیک ٹھاک پھرتے ہیں بس زمانہ ذرا اداس ہے"},{"slug":"tum-p040","body":"آج بےحد دنوں کے بعد یونہی  بےسبب\nدل کے ویران غوشوں سے  اک روشنی اٹھی\nجیسے کسی آس میں سما  گیا یادوں کا  سمندر\nجیسے درد کے سنساں جنگلوں میں تیز ہوا چلی\n\nپھیل گئی فرقت کے باغیچوں میں تمناؤں کی اوس\nفضا سنساں ، ہر گل محک رہا، ہر کلی جھوم اٹھی\nکسی سمت نہیں ہے ذکرِ فراقِ جاناں کی صدا\nہجر کی گھڑیوں میں اٹھا شور ، کہ بہار آئی\n\nموسم بدلنے کو ہے مگر تیرا نشاں ہے کہاں\nتم نہیں ہو نظر میں مگر پھر بھی ہو یہاں\nدلوں کی تاریکیوں میں ، خوابوں میں ، ہوا میں\nلبوں پہ صاف عیاں اور سوچوں میں  پنہاں\n\nاگرچہ یہ روشنی بس کچھ پل کے لیے ہے\nمگر یہ آس جو جلی ہے یہ نہ بجھ سکے گی\nہم لوگ تو مر جائیں گے ، دل بجھ جائے گا\nمگر یہ محبت ہے احمد جو باقی رہے گی"}]$bodies$::jsonb) x
) as x
where p.slug = x.slug;
